import sys 
mod=998244353
def interval_mask(l,h):
    if l>h:
        return 0
    return((1<<(h+1))-1)^((1<<l)-1)
def get_mask(v,n,occ):
    full=(1<<v)-1
    lm=full
    rm=full
    for i in occ:
        r=(i-1)//2 
        D=i-n+v-1
        pl=0
        if D<r:
            if 0<=r<v:
                pl=1<<r 
        elif D==r:
            pl=interval_mask(0,r)
        pr=0
        if D==r:
            pr=interval_mask(0,r)
        q=(n-i)//2 
        E=v-i
        sl=0
        if E==q:
            sl=interval_mask(i-1,v-1)
        sr=0
        if E<q:
            c0=v-1-q
            if 0<=c0<v:
                sr=1<<c0
        elif E==q:
            sr=interval_mask(i-1,v-1)
        al=pl|sl
        ar=pr|sr
        lm&=al
        rm&=ar
        if lm==0 and rm==0:
            break
    return lm,rm
def solve():
    input=sys.stdin.readline
    t=int(input())
    for _ in range(t):
        n=int(input())
        a=list(map(int,input().split()))
        oc=[[]for _ in range(n+1)]
        for i,x in enumerate(a,1):
            oc[x].append(i)
        posn=oc[n]
        if len(posn)>1 or (posn and posn[0]!=1 and posn[0]!=n):
            print(0)
            continue
        dp=[0]*n
        dp[0]=1 
        for v in range(1,n):
            lm,rm=get_mask(v,n,oc[v])
            ndp=[0]*n
            for c in range(v):
                w=dp[c]
                if w==0:
                    continue 
                if (lm>>c)&1:
                    ndp[c+1]+=w
                    if ndp[c+1]>=mod:
                        ndp[c+1]-=mod
                if (rm>>c)&1:
                    ndp[c]+=w
                    if ndp[c]>=mod:
                        ndp[c]-=mod
            dp=ndp
        if posn:
            if posn[0]==1:
                print(dp[0])
            else:
                print(dp[n-1])
        else:
            print(sum(dp)%mod)
if __name__=="__main__":
    solve()
